fn sample(id:i64,x:f64)f64{if(id==0)return x*x;return x*x*x-x*x+378.0;}
export fn integral_approximation(v:[*]const i64,n:usize)f64{if(n!=4)return -1.0e300;const id=v[0];const li=v[1];const ui=v[2];const di=v[3];if(id<0 or id>1 or li<0 or ui>32 or li>=ui or di<1 or di>8)return -1.0e300;const lo=@as(f64,@floatFromInt(li))/8.0;const hi=@as(f64,@floatFromInt(ui))/8.0;const d=@as(f64,@floatFromInt(di))/8.0;const count:usize=@intFromFloat((hi-lo)/d);if(count>32)return -1.0e300;var total:f64=0;for(0..count)|i|{const begin=lo+@as(f64,@floatFromInt(i))*d;const finish=lo+@as(f64,@floatFromInt(i+1))*d;total+=d*(sample(id,begin)+sample(id,finish))/2.0;}return total;}
